INSERT INTO public.sections (id, type, title, content, "order", is_visible, created_at, updated_at) VALUES (10, 'project', 'Projects', '{"raw": "", "items": [{"cta": "More...", "name": "At Fault Accident Claim Gosai Law SEO Ranks on First Page in two months", "tags": "SEO Blog Ranking, SEO keywords,", "image": "./assets/at-fault-accident-claim-gosai-law-seo.gif", "description": "Wrote a blog about At Fault Accident Claim which ranks on the first page of Google. It was written in May 2025 and got its ranking in the month of July 2025"}, {"cta": "More...", "name": "CPP Disability Denial Appeal on Google search results on first page in just a month", "tags": "SEO blog ranking, SEO keywords, SEO blog", "image": "./assets/cpp-disability-denial-claim-gosai-law-seo.gif", "description": "Wrote a blog on CPP Denial Decision Appeal which ranks on the first page of Google. It was written in April 2025 and got its ranking in the month of May 2025."}, {"cta": "More...", "name": "Email Metrics For the last few Emails sent", "tags": "Email Marketing, Email Set Up, MailChimp", "image": "./assets/email-metrics-deep.png", "description": "Here are some metrics from the last few emails sent."}, {"cta": "More...", "name": "Gosai Law Email Metrics", "tags": "Email Marketing, Email Set Up, MailChimp", "image": "./assets/gosai-law-email-metrics.png", "description": "Here are some metrics from the last few emails sent."}, {"cta": "More...", "name": "Cloudnineview Social Media Metrics", "tags": "Social Media Marketing, Social Media Strategy, Content Marketing, Follower Growth", "image": "./assets/cloudnineviews-social-media-metrics.png", "description": "I helped this client of mine gain followers in 69 days and received 13K+ profile views in 30 days span."}, {"cta": "More...", "name": "I am Fine Therapy POV Meme Metrics", "tags": "Social Media Marketing, Social Media Strategy, Content Marketing, Follower Growth", "image": "./assets/i-am-fine-therapy-pov-meme-metrics.mp4", "description": "Reel insights for one of the best performing reel from the past few days (July 2025)."}, {"cta": "More...", "name": "Do you read between the lines Reel Insights", "tags": "Social Media Marketing, Social Media Strategy, Content Marketing, Follower Growth", "image": "./assets/do-you-read-between-the-lines-reel-insights.mp4", "description": "Reel insights for another one of the best performing reel from the past few days (July 2025)."}, {"cta": "More...", "name": "3.9k views for therapy client in last 30 days", "tags": "Social Media Marketing, Social Media Strategy, Content Marketing, Follower Growth", "image": "./assets/profile-views-in-last-30-days.png", "description": "3.9k views in last 30 days"}, {"cta": "More...", "name": "Therapy Insights July 8 to Aug 6", "tags": "Social Media Marketing, Social Media Strategy, Content Marketing, Follower Growth", "image": "./assets/therapy-insights-july-8-to-aug-6.png", "description": "Insights for last 30 days July 8 to Aug 6"}, {"cta": "More...", "name": "Followers Metrics TikTok", "tags": "Social Media Marketing, Social Media Strategy, Content Marketing, Follower Growth", "image": "./assets/followers-metrics-tiktok.png", "description": "Recent follower insights on TikTok"}, {"cta": "More...", "name": "TikTok Analytics 28 days Jul 10 to Aug 6", "tags": "Social Media Marketing, Social Media Strategy, Content Marketing, Follower Growth", "image": "./assets/tiktok-analytics-28-days-jul-10-to-aug-6.png", "description": "Recent key metrics on TikTok"}, {"cta": "More...", "name": "Top Posts TikTok Analytics", "tags": "Social Media Marketing, Social Media Strategy, Content Marketing, Follower Growth", "image": "./assets/top-posts-tiktok-analytics.png", "description": "Top post performance in last 28 days"}, {"cta": "More...", "name": "Viewers Metrics TikTok", "tags": "Social Media Marketing, Social Media Strategy, Content Marketing, Follower Growth", "image": "./assets/viewers-metrics-tiktok.png", "description": "Viewers metrics on TikTok"}, {"cta": "Stacker", "name": "One More Project", "tags": "Stack 1, Stack 2", "image": "/uploads/1769232473868-81484807-WorkEx_Local.png", "description": "Some Desci"}]}', 6, NULL, '2026-01-24 00:30:56.944661+00', '2026-01-24 05:55:42.2255+00');
INSERT INTO public.sections (id, type, title, content, "order", is_visible, created_at, updated_at) VALUES (9, 'experience', 'Work Experience', '{"raw": "", "items": [{"end": "Present", "city": "Remote (Ontario)", "start": "Apr 2025", "company_name": "Gosai Law", "on_field_work": "• Helping with SEO strategy, blog optimization, and performance tracking (one blog ranked Page 1 on Google in June 2025)\n• Building and updating WordPress pages (including on-page SEO and formatting legal blogs)\n• Planning and analyzing Mailchimp campaigns with 39.9% open rate and 1.3% CTR\n• Instagram growth: +356 followers (Jan–June), TikTok growth: +92 followers (3.11% increase in 7 days)\n• Highest-performing reel: 2401 views, 27 shares, 107 likes in July 2025"}, {"end": "Present", "city": "Remote (Ontario)", "start": "Mar 2025", "company_name": "4teentherapy", "on_field_work": "• Social Media Strategist - Plan Content, Work on Creatives on Canva and Photoshop, Post according to Content Calendar\n• Create strategy for Instagram, Facebook and TikTok\n• Goal: To get teen clients through organic posting\n• Organic posting helped my client get two teen clients in two months"}, {"end": "Jan 2025", "city": "Remote (Ontario)", "start": "Dec 2024", "company_name": "Footwear Brand", "on_field_work": "• Achieved 16.9x ROAS in 1 month through video, carousel, and UGC ads (through constant optimization and A/B testing)\n• Budget: $1.1K | Sales: 900 | Conversion Value: $19.2K"}, {"end": "Jan 2025", "city": "Remote (Ontario)", "start": "Oct 2024", "company_name": "Cloud Nine Views", "on_field_work": "• Social Media Strategist - Plan content, find relevant videos from shared folder of drone captures by Client\n• Through tavel storytelling and community building I helped my Client gain 500 new followers in 59 days\n• Gaining Followers was the main goal"}, {"end": "Oct 2025", "city": "Remote (Ontario)", "start": "Aug 2024", "company_name": "Dentist", "on_field_work": "• Ran lead gen ads for high-ticket dental makeovers | Cost per lead: $4.40\n• Total leads: 681 | Budget: $2.2K"}, {"end": "May 2023", "city": "Mumbai, India", "start": "Jul 2022", "company_name": "Neon Digital Media", "on_field_work": "• Developed, executed & optimized paid advertising campaigns across Meta (FB, IG) & LinkedIn.\n• Reduced Cost-per-Acquisition (CPA) by 6.67% & boosted conversion rates by 5%.\n• A/B tested 60+ ad creatives, leading to an 8.33% increase in audience engagement\n• Collaborated with cross-functional teams (design, sales) to implement campaign strategies that resulted in increase in ROAS by 1.10% exceeding client targets.\n• Monitored and analyzed campaign data to identify actionable insights, optimize campaign performance, and provide UI/UX recommendations."}, {"end": "Jun 2022", "city": "Remoce, Mumbai, India", "start": "Mar 2022", "company_name": "Amrutam: Ayurvedic Lifestyle & Wellness Brand", "on_field_work": "• Led the development and execution of data-driven Meta and Google Ads campaigns, achieving a 1.75% increase in ROAS and exceeding revenue targets by $411 within 3 months.\n• Developed and implemented an email marketing strategy that converted leads into 35 orders.\n• Executed an influencer marketing outreach campaign that generated 5 orders within 9 days.\n• Created and implemented social media marketing strategies that increased engagement by 3%"}]}', 1, NULL, '2026-01-24 00:30:56.941548+00', '2026-01-24 04:03:40.542531+00');
INSERT INTO public.sections (id, type, title, content, "order", is_visible, created_at, updated_at) VALUES (13, 'hidden', 'Pricing', '{"raw": "", "items": [{"price": "CAD$750/Month", "title": "Social Media Management", "details": "– 3 posts per week (mix of reels and static posts)\n– monthly content planning and content calendar\n– caption writing and hashtag research\n– basic community management (replying to comments)\n– monthly performance report with insights and recommendations"}]}', 3, true, '2026-01-24 05:54:23.628042+00', '2026-01-24 06:03:07.063947+00');
